// readers of `state` never lock; writers publish a whole new snapshot
let state = Object.freeze({ routes: {}, version: 0 });

function addRoute(k, v) {
  state = Object.freeze({                      // new snapshot, unchanged parts shared
    ...state,
    version: state.version + 1,
    routes: Object.freeze({ ...state.routes, [k]: v }),
  });
}

const { routes } = state;   // read once, then work off the snapshot you got
